	/** 
	 * jumpstart the process by instantiating2 Incident
	 */
	protected void jumpStart() throws Throwable {
		LOGGER.info( "\n======== create instances to get the ball rolling  ======== ");

		incidentId = IncidentService.getIncidentInstance()
		.createIncident( generateNewCommand() )
		.get();

		// ---------------------------------------------
		// set up query subscriptions after the 1st create
		// ---------------------------------------------
		testingStep = "create";
		setUpQuerySubscriptions();

		IncidentService.getIncidentInstance()
				.createIncident( generateNewCommand() )
				.get();

	}

	/** 
	 * Set up query subscriptions
	 */
	protected void setUpQuerySubscriptions() throws Throwable {
		LOGGER.info( "\n======== Setting Up Query Subscriptions ======== ");
			
		try {            
			subscriber.incidentSubscribe().updates().subscribe(
					  successValue -> {
						  LOGGER.info(successValue.toString());
						  try {
							  LOGGER.info("GetAll update received for Incident : " + successValue.getIncidentId());
							  if (successValue.getIncidentId().equals(incidentId)) {
								  if (testingStep.equals("create")) {
									  testingStep = "update";
									  update();
								  } else if (testingStep.equals("delete")) {
									  testingStep = "complete";
									  state( getAll().size() == sizeOfIncidentList - 1 , "value not deleted from list");
									  LOGGER.info("**********************************************************");
									  LOGGER.info("Incident test completed successfully...");
									  LOGGER.info("**********************************************************\n");
								  }
							  }
						  } catch( Throwable exc ) {
							  LOGGER.warning( exc.getMessage() );
						  }
					  },
					  error -> LOGGER.warning(error.getMessage()),
					  () -> LOGGER.info("Subscription on incident consumed")
					);
			subscriber.incidentSubscribe( incidentId ).updates().subscribe(
					  successValue -> {
						  LOGGER.info(successValue.toString());
						  try {
							  LOGGER.info("GetOne update received for Incident : " + successValue.getIncidentId() + " in step " + testingStep);
							  testingStep = "delete";
							  sizeOfIncidentList = getAll().size();
							  delete();
						  } catch( Throwable exc ) {
							  LOGGER.warning( exc.getMessage() );
						  }
					  },
					  error -> LOGGER.warning(error.getMessage()),
					  () -> LOGGER.info("Subscription on incident for incidentId consumed")

					);
			

			}
			catch (Exception e) {
				LOGGER.warning( e.getMessage() );
				throw e;
			}
		}
		
		/** 
	 * read a Incident. 
	 */
	protected Incident read() throws Throwable {
		LOGGER.info( "\n======== READ ======== ");
		LOGGER.info( "-- Reading a previously created Incident" );

		Incident entity = null;
		StringBuilder msg = new StringBuilder( "-- Failed to read Incident with primary key" );
		msg.append( incidentId );
		
		IncidentFetchOneSummary fetchOneSummary = new IncidentFetchOneSummary( incidentId );

		try {
			entity = IncidentService.getIncidentInstance().getIncident( fetchOneSummary );

			assertNotNull( entity,msg.toString() );

			LOGGER.info( "-- Successfully found Incident " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return entity;
	}

	/** 
	 * updating a Incident.
	 */
	protected void update() throws Throwable {
		LOGGER.info( "\n======== UPDATE ======== ");
		LOGGER.info( "-- Attempting to update a Incident." );

		StringBuilder msg = new StringBuilder( "Failed to update a Incident : " );        
		Incident entity = read();
		UpdateIncidentCommand command = generateUpdateCommand();
		command.setIncidentId(entity.getIncidentId());

		try {            
			assertNotNull( entity, msg.toString() );

			LOGGER.info( "-- Now updating the created Incident." );

			// for use later on...
			incidentId = entity.getIncidentId();

			IncidentService proxy = IncidentService.getIncidentInstance();  

			proxy.updateIncident( command ).get();

			LOGGER.info( "-- Successfully saved Incident - " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : primarykey = " + incidentId + " : command -" +  command + " : " + e );

			throw e;
		}
	}

	/** 
	 * delete a Incident.
	 */
	protected void delete() throws Throwable {
		LOGGER.info( "\n======== DELETE ======== ");
		LOGGER.info( "-- Deleting a previously created Incident." );

		Incident entity = null;
		
		try{
		    entity = read(); 
			LOGGER.info( "-- Successfully read Incident with id " + incidentId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to read Incident with id " + incidentId );

			throw e;
		}

		try{
			IncidentService.getIncidentInstance().delete( new DeleteIncidentCommand( entity.getIncidentId() ) ).get();
			LOGGER.info( "-- Successfully deleted Incident with id " + incidentId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to delete Incident with id " + incidentId );

			throw e;
		}
	}

	/**
	 * get all Incidents.
	 */
	protected List<Incident> getAll() throws Throwable {    
		LOGGER.info( "======== GETALL ======== ");
		LOGGER.info( "-- Retrieving Collection of Incidents:" );

		StringBuilder msg = new StringBuilder( "-- Failed to get all Incident : " );        
		List<Incident> collection  = new ArrayList<>();

		try {
			// call the static get method on the IncidentService
			collection = IncidentService.getIncidentInstance().getAllIncident();
			assertNotNull( collection, "An Empty collection of Incident was incorrectly returned.");
			
			// Now print out the values
			Incident entity = null;            
			Iterator<Incident> iter = collection.iterator();
			int index = 1;

			while( iter.hasNext() ) {
				// Retrieve the entity   
				entity = iter.next();

				assertNotNull( entity,"-- null entity in Collection." );
				assertNotNull( entity.getIncidentId(), "-- entity in Collection has a null primary key" );        

				LOGGER.info( " - " + String.valueOf(index) + ". " + entity.toString() );
				index++;
			}
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return collection;			
	}

